/// <summary>
/// Service class to send sales order cancellation business event as a batch
/// </summary>
class METSendSalesOrderCancelledBusinessEventService extends SysOperationServiceBase
{
    InfoMessage errorMessage;

}

Method.Source:
    /// <summary>
    /// Process the sales order cancellations.
    /// </summary>
    public void process()
    {
        SalesLine      salesLine;
        METSalesLine   metSalesLine;

        try
        {
            select firstonly SalesId, RecId from salesLine 
                join RecId from metsalesLine
                    where metSalesLine.SalesLine == salesLine.RecId
                       && salesLine.SalesStatus == SalesStatus::Canceled
                       && metSalesLine.IntegrationStatus  == METIntegrationStatus::ReadyToSend;

            if(salesLine.RecId)
            {
                if(BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METSalesOrderCancelledBusinessEvent)))
                {
                    METSalesOrderCancelledBusinessEvent::newFromDataAreaId(curExt()).send();
                }
                else
                {
                    throw error("@MET:SOCancellationBusinessEventNotEnabled");
                }
            }
        }
        catch(Exception::Error)
        {
            this.getInfologMessage();            
            throw error(errorMessage);
        }
    }

    /// <summary>
    /// Gets the latest infolog error message
    /// </summary>
    private void getInfologMessage()
    {
        SysInfologEnumerator sysInfologEnumerator;
        SysInfologMessageStruct sysInfologMessageStruct;

        sysInfologEnumerator = SysInfologEnumerator::newData(infolog.infologData());
        errorMessage = METConstants::emptyString;

        while (sysInfologEnumerator.moveNext())
        {
            sysInfologMessageStruct = new SysInfologMessageStruct(sysInfologEnumerator.currentMessage());
            errorMessage += strfmt(sysInfologMessageStruct.message());
        }
    }
